use horizon_client::mobs::model_layers::{CubeDeformation, CubeListBuilder, LayerDefinition, MeshDefinition, ModelPart, PartPose};
pub(super) fn adult() -> ModelPart {
    let mut mesh = MeshDefinition::new();
    let partdefinition = mesh.root();
    let root = mesh.add_or_replace_child(partdefinition, "root", CubeListBuilder::create(), PartPose::offset(0.0, 24.0, 0.0));
    let rolled = mesh.add_or_replace_child(root, "rolled", CubeListBuilder::create().tex_offs(30, 1).add_box_with([-3.0, -2.25, -3.25], [6.0, 5.0, 6.0], CubeDeformation::new(0.0)).tex_offs(25, 25).add_box_with([-2.0, -3.25, -4.25], [4.0, 7.0, 8.0], CubeDeformation::new(0.0)).tex_offs(26, 16).add_box_with([-5.0, -4.25, 1.75], [10.0, 8.0, 0.0], CubeDeformation::new(0.0)).tex_offs(26, 16).add_box_with([-5.0, -4.25, -1.25], [10.0, 8.0, 0.0], CubeDeformation::new(0.0)), PartPose::offset(0.0, -3.75, 0.25));
    let unrolled = mesh.add_or_replace_child(root, "unrolled", CubeListBuilder::create(), PartPose::offset(0.0, 0.0, 0.0));
    let body = mesh.add_or_replace_child(unrolled, "body", CubeListBuilder::create().tex_offs(0, 0).add_box_with([-3.0, -2.5, -3.5], [6.0, 5.0, 7.0], CubeDeformation::new(0.01)).tex_offs(0, 16).add_box_with([-5.0, -4.5, -2.5], [10.0, 4.0, 0.0], CubeDeformation::new(0.0)).tex_offs(0, 21).add_box_with([-5.0, -4.5, 0.0], [10.0, 5.0, 0.0], CubeDeformation::new(0.0)).tex_offs(0, 26).add_box_with([-5.0, -4.5, 2.5], [10.0, 5.0, 0.0], CubeDeformation::new(0.0)).tex_offs(5, 4).set_mirror(true).add_box_with([3.0, -2.5, -3.5], [1.0, 2.0, 0.0], CubeDeformation::new(0.0)).set_mirror(false).tex_offs(5, 4).add_box_with([-4.0, -2.5, -3.5], [1.0, 2.0, 0.0], CubeDeformation::new(0.0)), PartPose::offset(0.0, -3.0, -0.5));
    let snout = mesh.add_or_replace_child(body, "snout", CubeListBuilder::create().tex_offs(0, 12).add_box_with([-1.0, -1.0, -2.0], [2.0, 2.0, 2.0], CubeDeformation::new(0.0)).tex_offs(13, 13).add_box_with([-0.5, -1.5, -2.5], [1.0, 1.0, 1.0], CubeDeformation::new(0.0)), PartPose::offset(0.0, 1.5, -3.5));
    let legs = mesh.add_or_replace_child(unrolled, "legs", CubeListBuilder::create(), PartPose::offset(0.0, -1.0, -0.5));
    let left_arm = mesh.add_or_replace_child(legs, "left_arm", CubeListBuilder::create().tex_offs(21, 3).set_mirror(true).add_box_with([-1.0, 0.0, -1.0], [2.0, 1.0, 2.0], CubeDeformation::new(0.0)).set_mirror(false).tex_offs(21, 0).set_mirror(true).add_box_with([-1.0, 0.0, -1.0], [2.0, 1.0, 2.0], CubeDeformation::new(0.1)).set_mirror(false), PartPose::offset(1.75, 0.0, -1.5));
    let right_arm = mesh.add_or_replace_child(legs, "right_arm", CubeListBuilder::create().tex_offs(21, 3).add_box_with([-1.0, 0.0, -1.0], [2.0, 1.0, 2.0], CubeDeformation::new(0.0)).tex_offs(21, 0).add_box_with([-1.0, 0.0, -1.0], [2.0, 1.0, 2.0], CubeDeformation::new(0.1)), PartPose::offset(-1.75, 0.0, -1.5));
    let left_leg = mesh.add_or_replace_child(legs, "left_leg", CubeListBuilder::create().tex_offs(21, 3).set_mirror(true).add_box_with([-1.0, 0.0, -1.0], [2.0, 1.0, 2.0], CubeDeformation::new(0.0)).set_mirror(false).tex_offs(21, 0).set_mirror(true).add_box_with([-1.0, 0.0, -1.0], [2.0, 1.0, 2.0], CubeDeformation::new(0.1)).set_mirror(false), PartPose::offset(1.75, 0.0, 1.5));
    let right_leg = mesh.add_or_replace_child(legs, "right_leg", CubeListBuilder::create().tex_offs(21, 3).add_box_with([-1.0, 0.0, -1.0], [2.0, 1.0, 2.0], CubeDeformation::new(0.0)).tex_offs(21, 0).add_box_with([-1.0, 0.0, -1.0], [2.0, 1.0, 2.0], CubeDeformation::new(0.1)), PartPose::offset(-1.75, 0.0, 1.5));
    LayerDefinition::create(mesh, 64, 64).bake_root()
}
